// Generated by Claude/specs/courses-tools/sync-hr.js from Claude/specs/lxd-course-hr-pilot/out-rounds/hr-pilot-block.js. Do not hand-edit.
(function(E){ const x = E["hr-m4"] = E["hr-m4"] || {units:{}}; x.units["hr-4-4"] = {"explain":{"id":"c-hr-4-4-e","course":"hr","unit":"hr-4-4","type":"explain","level":"B1","title":{"en":"Difficult conversations","tr":"Zor konuşmalar","fa":"گفتگوهای دشوار"},"objective":{"en":"After this lesson, you can raise a problem such as lateness calmly and fairly, starting from facts.","tr":"Bu dersin sonunda geç kalma gibi bir sorunu olgulardan başlayarak sakin ve adil biçimde açabileceksin.","fa":"بعد از این درس می‌توانی مشکلی مثل دیر آمدن را آرام و منصفانه مطرح کنی و از واقعیت‌ها شروع کنی."},"hook":{"en":"Raise a problem with facts, then ask why. Raised early and calmly, it can often be solved without a formal warning. Omar wanted a written warning. Leyla opened with a fact and offered an idea, and found the real reason.","tr":"Bir sorunu olgularla aç, sonra nedenini sor. Erken ve sakince konuşulursa çoğu zaman resmî uyarıya gerek kalmadan çözülebilir. Omar yazılı uyarı istiyordu. Leyla bir bilgiyle başladı, bir öneri sundu ve asıl nedeni buldu.","fa":"مشکل را با واقعیت‌ها مطرح کن و بعد دلیلش را بپرس. اگر زود و آرام مطرحش کنی، خیلی وقت‌ها بدون اخطار رسمی حل می‌شود. عمر اخطار کتبی می‌خواست. لیلا با یک واقعیت شروع کرد، یک پیشنهاد داد و دلیل واقعی را پیدا کرد."},"before":{"en":"After a difficult talk, write a short note that confirms what you agreed: what changes, for how long, and when you will check in.","tr":"Zor bir konuşmadan sonra anlaştığınız şeyi teyit eden kısa bir not yaz: ne değişiyor, ne kadar süreyle ve ne zaman yeniden görüşeceksiniz.","fa":"بعد از یک گفتگوی سخت، یادداشت کوتاهی بنویس که توافقتان را تأیید کند: چه چیزی عوض می‌شود، برای چه مدت و کی دوباره صحبت می‌کنید."},"rounds":[[1,4],[2,3]],"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"4"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"3"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"5"}],"points":[{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"Start from facts, then ask why","tr":"Olgularla başla, sonra nedenini sor","fa":"از واقعیت‌ها شروع کن و بعد دلیلش را بپرس"},"body":{"en":"A label like \"always late\" makes people defend themselves, and you never learn the cause. So give the facts, ask what is happening and listen. Then offer an idea.","tr":"\"Hep geç kalıyorsun\" gibi bir etiket insanı savunmaya geçirir ve nedeni hiç öğrenemezsin. Bu yüzden olguları söyle, neler olduğunu sor ve dinle. Sonra bir fikir öner.","fa":"برچسبی مثل «همیشه دیر می‌آیی» آدم را به دفاع از خودش می‌اندازد و هیچ‌وقت دلیل را نمی‌فهمی. پس واقعیت‌ها را بگو، بپرس چه اتفاقی افتاده و گوش بده. بعد پیشنهادی بده."}},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Raising a problem: I've noticed that... and If we..., would...?","tr":"Bir sorunu açmak: I've noticed that... ve If we..., would...?","fa":"مطرح کردن مشکل: I’ve noticed that... و If we..., would...?"},"steps":[{"en":"Open with a recent pattern: I've noticed that...","tr":"Yakın zamandaki bir örüntüyle başla: I've noticed that...","fa":"با یک الگوی تکراری اخیر شروع کن: ⁨I've noticed that...⁩","ex":"I've noticed that you've arrived late four times in two weeks."},{"en":"Say what you saw, not who they are.","tr":"Kim olduğunu değil, ne gördüğünü söyle.","fa":"بگو چه دیده‌ای، نه اینکه او چه جور آدمی است.","ex":"not 'You are always late'"},{"en":"Offer an idea: If + past simple, would + verb?","tr":"Bir fikir sun: If + past simple, would + fiil?","fa":"یک پیشنهاد بده: در بخش if گذشته‌ی ساده بیاور و در بخش دوم would و فعل ساده.","ex":"If we moved your start to 8:30, would that help?"}],"table":{"headers":{"en":["Step","Example"],"tr":["Adım","Örnek"],"fa":["مرحله","مثال"]},"rows":[["Facts (present perfect)","I've noticed that you've arrived late four times."],["Ask","Can you help me understand what's been happening?"],["Offer (second conditional)","If we moved your start to 8:30, would that help?"],["Expectation","If this happens again, please tell Omar the day before."]]},"tip":{"en":"Persian 'agar saat-e shoru ra 8:30 mikardim, komak mikard?' uses the same past form in both halves. English uses the past only in the if-part and would in the other.","tr":"Türkçede 'Başlangıç saatini 8.30'a alsak işine yarar mı?' deriz. İngilizcede if kısmı past simple, diğer kısım would ile kurulur: If we moved..., would that help?","fa":"در فارسی می‌گوییم «اگر ساعت شروعت را ۸:۳۰ می‌کردیم، کمکی می‌کرد؟» و هر دو بخش شکل گذشته دارند. در انگلیسی فقط بخش if گذشته است و بخش دیگر would می‌گیرد."},"wrong":"If we changed your start time, it helped?","right":"If we changed your start time, would it help?"},{"eyebrow":{"en":"Key phrases","tr":"Anahtar ifadeler","fa":"عبارت‌های کلیدی"},"head":{"en":"Phrases for this task","tr":"Bu görev için ifadeler","fa":"عبارت‌های این کار"},"phrases":[{"phrase":"I wanted to talk about something I've noticed.","meaning":{"en":"Names the purpose without blame.","tr":"Suçlamadan amacı belirtir.","fa":"هدف گفتگو را بدون سرزنش می‌گوید."}},{"phrase":"Can you help me understand what's been happening?","meaning":{"en":"Asks before judging.","tr":"Yargılamadan önce sorar.","fa":"قبل از قضاوت، سؤال می‌کند."}},{"phrase":"If we..., would that help?","meaning":{"en":"Offers a solution to discuss.","tr":"Tartışılacak bir çözüm sunar.","fa":"راه‌حلی را برای گفتگو پیشنهاد می‌دهد."}}]},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Always in private","tr":"Her zaman baş başa","fa":"همیشه دونفره و دور از جمع"},"body":{"en":"Raising someone's behaviour in front of colleagues causes serious loss of face in Turkey, Iran and the Persian Gulf, and it is seen as unprofessional in the UK and US too. Always talk in private. In many UK companies a written warning is part of a formal process that should come after an informal conversation like this one, not before it.","tr":"Birinin davranışını iş arkadaşlarının önünde açmak Türkiye, İran ve Basra Körfezi'nde ciddi bir itibar kaybına yol açar; Birleşik Krallık ve ABD'de de profesyonellik dışı görülür. Her zaman baş başa konuş. Birçok İngiliz şirketinde yazılı uyarı, bunun gibi gayriresmî bir konuşmadan önce değil, sonra gelmesi gereken resmî bir sürecin parçasıdır.","fa":"مطرح کردن رفتار کسی جلوی همکارانش، در ترکیه، ایران و کشورهای حاشیه‌ی خلیج فارس ضربه‌ی جدی‌ای به آبروی او می‌زند و در بریتانیا و آمریکا هم کاری غیرحرفه‌ای به حساب می‌آید. همیشه در خلوت صحبت کن. در بسیاری از شرکت‌های بریتانیایی، اخطار کتبی بخشی از یک روند رسمی است و باید بعد از یک گفتگوی غیررسمی مثل همین بیاید، نه قبل از آن."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"From weak to strong","tr":"Zayıftan güçlüye","fa":"از برچسب و تهدید تا واقعیت و سؤال"},"text":"Facts: The person has been late three times this month. You don't know why.","item":"You're always late. Next time it's a warning.","why":{"en":"Weak: a label and a threat. Strong: a fact and a real question.","tr":"Zayıf: bir etiket ve bir tehdit. Güçlü: bir olgu ve gerçek bir soru.","fa":"نسخه‌ی اول یک برچسب و یک تهدید است. نسخه‌ی دوم یک واقعیت را می‌گوید و یک سؤال واقعی می‌پرسد."},"answer":"You've been late three times this month. Can you help me understand why?","cut":["always late","Next time it's a warning."],"cutHint":{"en":"Tap the label and the threat: they stop the person telling you why.","tr":"Etikete ve tehdide dokun: Kişinin sana nedenini anlatmasını engellerler.","fa":"روی برچسب و تهدید بزن: نمی‌گذارند آن آدم دلیلش را به تو بگوید."}},"quick":{"prompt":"Where do you raise someone’s lateness with them?","options":["In private","In the team meeting, so everyone learns","By email to the whole team"],"correct":0,"why":{"en":"In private: raising it in front of colleagues causes loss of face in many places, and it is unprofessional in the UK and US too.","tr":"Baş başa: Bunu iş arkadaşlarının önünde açmak birçok yerde kişiyi küçük düşürür; İngiltere’de ve ABD’de de profesyonelce görülmez.","fa":"در خلوت: مطرح کردنش جلوی همکارها در خیلی جاها باعث می‌شود آبرویش برود و در انگلیس و آمریکا هم غیرحرفه‌ای است."},"point":4,"hint2":{"en":"Think about how the person feels if colleagues are listening. Where can they explain without losing face?","tr":"İş arkadaşları dinliyorsa kişinin ne hissedeceğini düşün. Mahcup olmadan nerede açıklama yapabilir?","fa":"فکر کن اگر همکارها گوش بدهند آن آدم چه حسی دارد. کجا می‌تواند بدون اینکه آبرویش برود توضیح بدهد؟"}},"remember":{"en":"Is there would in the if-part? Move it to the other half of the sentence. Result of this lesson: you can raise a problem fairly. You also have a note of what you agreed.","tr":"if kısmında would var mı? Onu cümlenin öbür yarısına taşı. Bu dersin sonucu: bir sorunu adil biçimde konuşabilirsin ve elinde anlaştıklarınızın notu olur.","fa":"در بخش if کلمه‌ی would هست؟ ببرش به بخش دیگر جمله. حالا می‌توانی مشکلی را منصفانه مطرح کنی. یادداشت توافقتان هم آماده است."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Past regrets: should have, it would have helped if...","tr":"Geçmişe dair pişmanlık: should have, it would have helped if...","fa":"حسرت گذشته: should have، it would have helped if..."},"steps":[{"en":"Direct regret: should have + past participle.","tr":"Doğrudan pişmanlık: should have + past participle.","fa":"برای افسوس مستقیم، should have و اسم مفعول را به کار ببر.","ex":"You should have called me."},{"en":"Softer: It would have helped if + had + past participle.","tr":"Daha yumuşak: It would have helped if + had + past participle.","fa":"نرم‌ترش این است: It would have helped if و بعد had با اسم مفعول.","ex":"It would have helped if you had told us earlier."},{"en":"Then look forward.","tr":"Sonra ileriye bak.","fa":"بعد به آینده نگاه کن.","ex":"Next time, please tell Omar the day before."}],"table":{"headers":{"en":["Pattern","Example","Tone"],"tr":["Kalıp","Örnek","Ton"],"fa":["الگو","مثال","لحن"]},"rows":[["should have + past participle","You should have called me.","direct, can sound critical"],["It would have helped if + had + past participle","It would have helped if you had told us earlier.","softer, better for HR"],["Next time, please...","Next time, please tell Omar the day before.","looks forward"]]},"body":{"en":"B2 track: in the conversation, use \"It would have helped if you had...\" once (not \"You should have\"), then move forward with \"Next time, please...\".","tr":"B2 yolu: konuşmada bir kez \"It would have helped if you had...\" kullan (\"You should have\" değil), sonra \"Next time, please...\" ile ileriye bak.","fa":"مسیر B2: در گفتگو یک بار از «⁨It would have helped if you had...⁩» استفاده کن (نه «You should have»)، و بعد با «⁨Next time, please...⁩» به آینده نگاه کن."}},"source":{"en":"Informed by the Acas Code of Practice: an informal talk comes before any warning.","tr":"Acas uygulama kurallarından yararlanır: her uyarıdan önce resmî olmayan bir görüşme gelir.","fa":"با استفاده از آیین‌نامه‌ی Acas: قبل از هر تذکری، اول یک گفتگوی غیررسمی."}},"grammar":{"id":"c-hr-4-4-g","level":"B1","course":"hr","unit":"hr-4-4","title":"Raising a problem: I've noticed that... and If we..., would...?","titleTr":"Bir sorunu açmak: I've noticed that... ve If we..., would...?","exp":{"en":"A difficult conversation needs facts first and a solution second. Open with the present perfect for a recent pattern: \"I've noticed that you've arrived late four times in the last two weeks.\" It names what you saw, not who the person is (not \"You are always late\"). Then offer a solution with the second conditional, which sounds like an idea to discuss, not an order: \"If we moved your start to 8:30, would that help?\", \"If you told us earlier, we would change your route.\" Form: If + past simple, would + base verb. No would in the if-part: not \"If you would tell us\". The past form here is about politeness and possibility, not past time.","tr":"Zor bir konuşmada önce olgular, sonra çözüm gelir. Yakın zamandaki bir örüntü için present perfect ile aç: \"I've noticed that you've arrived late four times in the last two weeks.\" Bu cümle kişinin kim olduğunu değil, ne gördüğünü söyler (\"You are always late\" değil). Sonra çözümü second conditional ile öner; bu bir emir gibi değil, tartışılacak bir fikir gibi durur: \"If we moved your start to 8:30, would that help?\", \"If you told us earlier, we would change your route.\" Biçim: If + past simple, would + yalın fiil. If'li kısımda would yok: \"If you would tell us\" değil. Buradaki geçmiş biçim zamanla değil, kibarlık ve olasılıkla ilgilidir.","fa":"گفتگوی دشوار اول به واقعیت نیاز دارد و بعد به راه‌حل. با حال کامل شروع کن تا از یک الگوی تکراریِ اخیر حرف بزنی: «⁨I've noticed that you've arrived late four times in the last two weeks.⁩» این جمله می‌گوید تو چه دیده‌ای، نه اینکه طرف «چه جور آدمی است» (نه «You are always late»). بعد راه‌حل را با شرطی نوع دوم پیشنهاد کن؛ این ساختار لحن «پیشنهادی برای گفتگو» دارد، نه «دستور»: «⁨If we moved your start to 8:30, would that help?⁩» و «⁨If you told us earlier, we would change your route.⁩» ساختار: if + گذشته‌ی ساده و would + فعل ساده. در بخش if، would نمی‌آید: نه «If you would tell us». زمان گذشته اینجا به گذشته اشاره نمی‌کند؛ فقط جمله را مؤدبانه‌تر و فرضی‌تر می‌کند، مثل «اگر ساعت شروع را ۸:۳۰ می‌کردیم، کمکی می‌کرد؟» در فارسی."},"formsTable":{"headers":{"en":["Step","Example"],"tr":["Adım","Örnek"],"fa":["مرحله","مثال"]},"rows":[["Facts (present perfect)","I've noticed that you've arrived late four times."],["Ask","Can you help me understand what's been happening?"],["Offer (second conditional)","If we moved your start to 8:30, would that help?"],["Expectation","If this happens again, please tell Omar the day before."]]},"wrong":"If you would tell us earlier, we would change your start time.","right":"If you told us earlier, we would change your start time.","blank":{"sentence":"If you ___ us earlier, we would change your start time.","word":"told","distractors":["will tell","have told"]},"wrong2":"I've notice that you have been late four times.","right2":"I've noticed that you have been late four times.","blank2":{"sentence":"I've ___ that you have been late four times this month.","word":"noticed","distractors":["notice","noticing"]},"expParts":{"tryFrom":"blank","hook":{"en":"Omar wanted a written warning. Leyla opened with a fact and offered an idea, and found the real reason.","tr":"Omar yazılı uyarı istiyordu. Leyla bir bilgiyle başladı, bir öneri sundu ve asıl nedeni buldu.","fa":"عمر اخطار کتبی می‌خواست. لیلا با یک واقعیت شروع کرد، یک پیشنهاد داد و دلیل واقعی را پیدا کرد."},"tryWhy":{"en":"told: in the if-part of a second conditional use the past simple. would and will stay out of it.","tr":"told: ikinci tip koşulun if kısmında past simple kullanılır. would ve will oraya girmez.","fa":"جواب told است: در بخش if شرطی نوع دوم گذشته‌ی ساده می‌آید. would و will آنجا جایی ندارند."},"rule":[{"en":"Open with a recent pattern: I've noticed that...","tr":"Yakın zamandaki bir örüntüyle başla: I've noticed that...","fa":"با یک الگوی تکراری اخیر شروع کن: ⁨I've noticed that...⁩","ex":"I've noticed that you've arrived late four times in two weeks."},{"en":"Say what you saw, not who they are.","tr":"Kim olduğunu değil, ne gördüğünü söyle.","fa":"بگو چه دیده‌ای، نه اینکه او چه جور آدمی است.","ex":"not 'You are always late'"},{"en":"Offer an idea: If + past simple, would + verb?","tr":"Bir fikir sun: If + past simple, would + fiil?","fa":"یک پیشنهاد بده: در بخش if گذشته‌ی ساده بیاور و در بخش دوم would و فعل ساده.","ex":"If we moved your start to 8:30, would that help?"}],"test":{"en":"Is there would in the if-part? Move it to the other half of the sentence.","tr":"if kısmında would var mı? Onu cümlenin öbür yarısına taşı.","fa":"در بخش if کلمه‌ی would هست؟ ببرش به بخش دیگر جمله."},"contrast":{"en":"Persian 'agar saat-e shoru ra 8:30 mikardim, komak mikard?' uses the same past form in both halves. English uses the past only in the if-part and would in the other.","tr":"Türkçede 'Başlangıç saatini 8.30'a alsak işine yarar mı?' deriz. İngilizcede if kısmı past simple, diğer kısım would ile kurulur: If we moved..., would that help?","fa":"در فارسی می‌گوییم «اگر ساعت شروعت را ۸:۳۰ می‌کردیم، کمکی می‌کرد؟» و هر دو بخش شکل گذشته دارند. در انگلیسی فقط بخش if گذشته است و بخش دیگر would می‌گیرد."}},"errorWatch":[{"find":["if you would tell","if we would move","if you would call","if we would change"],"fix":{"en":"No would in the if-part: 'If you told us earlier, we would change your start time.'","tr":"if kısmında would olmaz: 'If you told us earlier, we would change your start time.'","fa":"در بخش if کلمه‌ی would نمی‌آید: «⁨If you told us earlier, we would change your start time.⁩»"}},{"find":["i've notice","i have notice","you are always late","you're always late","you are lazy"],"fix":{"en":"Name the fact with 'I've noticed that...', not a label about the person.","tr":"Kişi hakkında etiket değil, 'I've noticed that...' ile bilgiyi söyle.","fa":"واقعیت را با «⁨I've noticed that...⁩» بگو، نه با برچسب زدن به آن فرد."}}]},"b2":{"id":"c-hr-4-4-b2","level":"B2","track":"B2","course":"hr","unit":"hr-4-4","title":"Past regrets: should have, it would have helped if...","titleTr":"Geçmişe dair pişmanlık: should have, it would have helped if...","exp":{"en":"To talk about what someone did not do in the past, B2 English uses should have + past participle: \"You should have called me when the school changed its times.\" It is direct and can sound like criticism. In HR conversations a softer version is often better: \"It would have helped if you had told us earlier.\" That is a third-conditional pattern: would have + past participle, and if + had + past participle. Check the forms: \"should have called\", never \"should called\" or \"should had called\"; \"if you had told\", not \"if you would tell\" or \"if you have told\".","tr":"Birinin geçmişte yapmadığı bir şeyden bahsetmek için B2 İngilizcesi should have + past participle kullanır: \"You should have called me when the school changed its times.\" Doğrudandır ve eleştiri gibi gelebilir. İK konuşmalarında çoğu zaman daha yumuşak bir biçim daha iyidir: \"It would have helped if you had told us earlier.\" Bu bir third conditional kalıbıdır: would have + past participle ve if + had + past participle. Türkçedeki \"keşke daha önce söyleseydin\" anlamına yakındır. Biçimleri kontrol et: \"should have called\"; asla \"should called\" ya da \"should had called\" değil. \"if you had told\"; \"if you would tell\" ya da \"if you have told\" değil.","fa":"برای حرف زدن درباره‌ی کاری که کسی در گذشته باید انجام می‌داد و نداد، در سطح B2 از should have + اسم مفعول استفاده می‌شود: «⁨You should have called me when the school changed its times.⁩» یعنی «باید به من زنگ می‌زدید». این جمله صریح است و ممکن است سرزنش‌آمیز به نظر برسد. در گفتگوهای منابع انسانی معمولاً شکل نرم‌تر بهتر جواب می‌دهد: «⁨It would have helped if you had told us earlier.⁩» یعنی «اگر زودتر به ما گفته بودید، کمک می‌کرد». این همان الگوی شرطی نوع سوم است: would have + اسم مفعول و if + had + اسم مفعول. شکل‌ها را دقیق بنویس: «should have called»، نه «should called» و نه «should had called»؛ و «if you had told»، نه «if you would tell» و نه «if you have told»."},"formsTable":{"headers":{"en":["Pattern","Example","Tone"],"tr":["Kalıp","Örnek","Ton"],"fa":["الگو","مثال","لحن"]},"rows":[["should have + past participle","You should have called me.","direct, can sound critical"],["It would have helped if + had + past participle","It would have helped if you had told us earlier.","softer, better for HR"],["Next time, please...","Next time, please tell Omar the day before.","looks forward"]]},"wrong":"You should called me when the school changed its times.","right":"You should have called me when the school changed its times.","blank":{"sentence":"You ___ called me when the school changed its times.","word":"should have","distractors":["should","should had"]},"wrong2":"It would have helped if you would tell us earlier.","right2":"It would have helped if you had told us earlier.","blank2":{"sentence":"It would have helped if you ___ me earlier.","word":"had told","distractors":["would tell","have told"]},"useIn":{"en":"B2 track: in the conversation, use \"It would have helped if you had...\" once (not \"You should have\"), then move forward with \"Next time, please...\".","tr":"B2 yolu: konuşmada bir kez \"It would have helped if you had...\" kullan (\"You should have\" değil), sonra \"Next time, please...\" ile ileriye bak.","fa":"مسیر B2: در گفتگو یک بار از «⁨It would have helped if you had...⁩» استفاده کن (نه «You should have»)، و بعد با «⁨Next time, please...⁩» به آینده نگاه کن."},"exitItem":{"from":"hr-4-4","kind":"blank","prompt":"You should ___ me about the childcare problem.","options":["have told","told","had told"],"correct":0,"why":{"en":"have told: 'should have' + past participle is a regret about the past. 'Should told' drops have, and 'should had told' is wrong.","tr":"have told: 'should have' + üçüncü hâl geçmişle ilgili bir pişmanlıktır. 'Should told' have'i düşürür; 'should had told' yanlıştır.","fa":"have told درست است، چون should have و اسم مفعول یعنی پشیمانی از گذشته. should told بدون have است و should had told غلط است."}},"expParts":{"hook":{"en":"'You should have called me' is true. 'It would have helped if you had told us' is gentler.","tr":"'You should have called me' doğru. 'It would have helped if you had told us' aynı mesajı daha yumuşak verir.","fa":"«You should have called me» درست است. «It would have helped if you had told us» همان پیام را نرم‌تر می‌رساند."},"tryWhy":{"en":"had told: in this if-part use had + past participle, never would.","tr":"had told: bu if kısmında had + past participle kullanılır, would asla.","fa":"جواب had told است: در این بخش if باید had و اسم مفعول بیاید، هرگز would."},"rule":[{"en":"Direct regret: should have + past participle.","tr":"Doğrudan pişmanlık: should have + past participle.","fa":"برای افسوس مستقیم، should have و اسم مفعول را به کار ببر.","ex":"You should have called me."},{"en":"Softer: It would have helped if + had + past participle.","tr":"Daha yumuşak: It would have helped if + had + past participle.","fa":"نرم‌ترش این است: It would have helped if و بعد had با اسم مفعول.","ex":"It would have helped if you had told us earlier."},{"en":"Then look forward.","tr":"Sonra ileriye bak.","fa":"بعد به آینده نگاه کن.","ex":"Next time, please tell Omar the day before."}],"test":{"en":"After should, look for have. After if, look for had. Both there? Correct.","tr":"should'dan sonra have'i, if'ten sonra had'i ara. İkisi de var mı? Doğru.","fa":"بعد از should دنبال have بگرد و بعد از if دنبال had. هر دو هست؟ درست است."},"contrast":{"en":"Persian 'bayad be man zang mizadi' and Turkish 'beni araman gerekirdi' do not show have + past participle, so learners write 'should called'. English needs should have called.","tr":"Türkçedeki 'beni araman gerekirdi' yapısında have + past participle yoktur; bu yüzden 'should called' yazılır. İngilizcede doğrusu: should have called.","fa":"در فارسی می‌گوییم «باید به من زنگ می‌زدی» و چیزی شبیه have و اسم مفعول نداریم؛ برای همین بعضی‌ها می‌نویسند «should called». درستش «should have called» است."}},"errorWatch":[{"find":["should called","should had","should told","if you would have told","helped if you would"],"fix":{"en":"Use should have + past participle, and if + had + past participle: 'It would have helped if you had told us.'","tr":"should have + past participle ve if + had + past participle kullan: 'It would have helped if you had told us.'","fa":"از should have و اسم مفعول، و از if با had و اسم مفعول استفاده کن: «It would have helped if you had told us.»"}}]},"vocab":{"id":"c-hr-4-4-v","level":"B1","category":"vocab","course":"hr","unit":"hr-4-4","goals":["career"],"title":{"en":"Difficult Conversations","tr":"Zor Konuşmalar","fa":"گفتگوهای دشوار"},"cards":[{"word":"lateness","sentence":"We need to talk about lateness.","meaning":{"en":"Arriving after the agreed time.","tr":"geç kalma.","fa":"تأخیر"}},{"word":"conduct","sentence":"Conduct issues are handled in private.","meaning":{"en":"The way someone behaves at work.","tr":"davranış, tutum.","fa":"رفتار و منش کاری"}},{"word":"pattern","sentence":"Four late days in two weeks is a pattern.","meaning":{"en":"Something that happens again and again in the same way.","tr":"örüntü, tekrar eden durum.","fa":"الگوی تکراری"}},{"word":"written warning","sentence":"Omar wanted to give him a written warning.","meaning":{"en":"A formal letter saying behaviour must change.","tr":"yazılı uyarı.","fa":"اخطار کتبی"}},{"word":"in private","sentence":"Always raise a problem in private.","meaning":{"en":"Where other people cannot hear.","tr":"baş başa, özel olarak.","fa":"خصوصی؛ دور از چشم و گوش دیگران"}},{"word":"personal circumstances","sentence":"His personal circumstances changed in May.","meaning":{"en":"Things happening in someone's private life.","tr":"kişisel durum.","fa":"شرایط شخصی"}},{"word":"adjust","sentence":"We can adjust your start time for a month.","meaning":{"en":"To change something a little.","tr":"ayarlamak, uyarlamak.","fa":"تعدیل کردن؛ کمی تغییر دادن"}},{"word":"support","sentence":"What support do you need from us?","meaning":{"en":"Help given to someone.","tr":"destek.","fa":"حمایت؛ پشتیبانی"}},{"word":"expectation","sentence":"Let's be clear about expectations.","gap":"expectations","accept":["expectations","expectation"],"meaning":{"en":"What someone thinks should happen.","tr":"beklenti.","fa":"انتظار (آنچه فکر می‌کنی باید اتفاق بیفتد)"}},{"word":"That isn't like you","sentence":"You're late again, and that isn't like you.","meaning":{"en":"This is different from how you usually are.","tr":"Bu sana hiç benzemiyor.","fa":"این کار از تو بعید است"}}]},"story":{"id":"c-hr-4-4-s","level":"B1","genre":"Workplace","course":"hr","unit":"hr-4-4","title":{"en":"Late Again","tr":"Yine Geç","fa":"باز هم دیر"},"text":"In May, Leyla flew to Dubai for a week. On her first morning, Omar met her at the door with a printout.\n\n\"Deniz,\" he said. \"Late four times in two weeks. Twenty minutes, every time. I want to give him a written warning today.\"\n\n\"Can I talk to him first?\"\n\nOmar sighed. \"You have until lunch.\"\n\nLeyla booked a small meeting room, not Omar's office with the glass walls. When Deniz came in, he did not sit back in the chair. He sat on the edge, ready to stand up.\n\n\"Thanks for coming,\" she said. \"I wanted to talk about something I've noticed. I've noticed that you've arrived late four times in the last two weeks. That isn't like you. In April you were early every day.\"\n\nDeniz looked at the table. \"I'm sorry. It won't happen again.\"\n\n\"Thank you. Before we talk about solutions, can you help me understand what's been happening?\"\n\nFor a moment he said nothing. Then it came out quickly, as if it had been waiting. His sister had an operation in early May. Since then he had been taking her daughter to school at 7:30. The school was on the other side of the city. He left the school at 7:35 and drove as fast as the law allowed, and it was never fast enough.\n\n\"Why didn't you tell anyone?\" Leyla asked gently.\n\n\"I'm new. New people don't bring problems.\"\n\nLeyla thought for a moment. \"If we moved your start to 8:30 for the next month, would that help? And if anything changes, tell Omar or me the day before.\"\n\nDeniz sat back in the chair for the first time.\n\nAt lunch Omar asked, \"Warning?\" Leyla shook her head. \"Schedule change. One month. I'll explain.\"","vocab":[{"word":"printout","en":"A paper copy from a computer.","tr":"çıktı","fa":"نسخه‌ی چاپی؛ پرینت"},{"word":"sigh","en":"To breathe out loudly when tired or annoyed.","tr":"iç çekmek","fa":"آه کشیدن"},{"word":"edge","en":"The outside end of something.","tr":"kenar","fa":"لبه"},{"word":"operation","en":"Here: when a doctor opens the body to treat it.","tr":"ameliyat","fa":"عمل جراحی"},{"word":"gently","en":"In a soft, kind way.","tr":"nazikçe","fa":"به‌آرامی؛ با ملایمت"}],"quiz":[{"prompt":"Why did Leyla choose a small meeting room?","options":["It was cheaper","So the conversation was private","Omar's office was busy"],"correct":1},{"prompt":"Choose the correct offer.","options":["If we moved your start to 8:30, would that help?","If we would move your start to 8:30, would that help?","If we move your start to 8:30, would that helped?"],"correct":0},{"prompt":"What was the real reason for the lateness?","options":["He did not like the route","He was taking his niece to school after his sister's operation","His alarm clock was broken"],"correct":1},{"prompt":"Why did Deniz not tell anyone?","options":["He felt new people should not bring problems","He forgot","He wanted to leave the job"],"correct":0}],"notice":{"en":"Omar wants a warning; Leyla wants a conversation. Watch how she opens, and the moment Deniz finally sits back in his chair.","tr":"Omar uyarı istiyor; Leyla ise bir konuşma. Konuşmayı nasıl açtığına ve Deniz'in sonunda sandalyesine yaslandığı ana dikkat et.","fa":"عمر اخطار می‌خواهد و لیلا گفتگو. دقت کن لیلا چطور شروع می‌کند و دنیز بالاخره کِی به صندلی تکیه می‌دهد."},"bridge":{"en":"'I've noticed that...' and 'If we moved your start to 8:30, would that help?' Next: see how they work.","tr":"'I've noticed that...' ve 'If we moved your start to 8:30, would that help?' Sırada: nasıl çalıştıklarını gör.","fa":"«⁨I've noticed that...⁩» و «⁨If we moved your start to 8:30, would that help?⁩» قدم بعد: ببین چطور کار می‌کنند."}},"speaking":{"id":"hr-4-4","course":"hr","unit":"hr-4-4","topic":{"en":"A Lateness Conversation","tr":"Geç Kalma Üzerine Bir Konuşma","fa":"گفتگو درباره‌ی تأخیر"},"warmup":{"en":"Have you ever had to tell someone something they did not want to hear? How did you start?","tr":"Hiç birine duymak istemediği bir şeyi söylemek zorunda kaldın mı? Nasıl başladın?","fa":"تا حالا مجبور شده‌ای حرفی به کسی بزنی که دوست نداشت بشنود؟ چطور شروع کردی؟"},"questions":[{"en":"Open in private and say why you asked to meet.","tr":"Baş başa aç ve neden görüşmek istediğini söyle.","fa":"گفتگو را در جایی خصوصی شروع کن و بگو چرا خواستی با او صحبت کنی."},{"en":"Give the facts with \"I've noticed that...\" and one positive note about the person.","tr":"\"I've noticed that...\" ile olguları ver ve kişi hakkında olumlu bir not ekle.","fa":"با «⁨I've noticed that...⁩» واقعیت‌ها را بگو و یک نکته‌ی مثبت درباره‌ی او هم اضافه کن."},{"en":"Ask what has been happening. Then offer one solution with \"If we..., would...?\" and state one clear expectation.","tr":"Neler olduğunu sor. Sonra \"If we..., would...?\" ile bir çözüm öner ve net bir beklenti söyle.","fa":"بپرس این مدت چه اتفاقی افتاده است. بعد با «⁨If we..., would...?⁩» یک راه‌حل پیشنهاد کن و بگو دقیقاً چه انتظاری داری."}],"followups":[{"en":"Do the whole conversation in 90 seconds, then 60, then 45.","tr":"Konuşmanın tamamını 90, sonra 60, sonra 45 saniyede yap.","fa":"کل گفتگو را یک بار در ۹۰ ثانیه، بعد در ۶۰ و بعد در ۴۵ ثانیه انجام بده."},{"en":"The employee gets defensive: \"Everyone is late sometimes!\" Stay with the facts, calmly.","tr":"Çalışan savunmaya geçiyor: \"Herkes bazen geç kalır!\" Sakin bir şekilde olgularda kal.","fa":"کارمند حالت دفاعی می‌گیرد: «⁨Everyone is late sometimes!⁩» آرام بمان و فقط به واقعیت‌ها تکیه کن."},{"en":"Now raise one small real problem at your work, with I have noticed that.","tr":"Şimdi işindeki küçük ama gerçek bir sorunu I have noticed that ile dile getir.","fa":"حالا یک مشکل کوچک و واقعی در کارت را با I have noticed that مطرح کن."}],"expressions":[{"phrase":"I wanted to talk about something I've noticed.","meaning":{"en":"Names the purpose without blame.","tr":"Suçlamadan amacı belirtir.","fa":"هدف گفتگو را بدون سرزنش می‌گوید."}},{"phrase":"Can you help me understand what's been happening?","meaning":{"en":"Asks before judging.","tr":"Yargılamadan önce sorar.","fa":"قبل از قضاوت، سؤال می‌کند."}},{"phrase":"If we..., would that help?","meaning":{"en":"Offers a solution to discuss.","tr":"Tartışılacak bir çözüm sunar.","fa":"راه‌حلی را برای گفتگو پیشنهاد می‌دهد."}}],"culture":{"en":"Raising someone's behaviour in front of colleagues causes serious loss of face in Turkey, Iran and the Persian Gulf, and it is seen as unprofessional in the UK and US too. Always talk in private. In many UK companies a written warning is part of a formal process that should come after an informal conversation like this one, not before it.","tr":"Birinin davranışını iş arkadaşlarının önünde açmak Türkiye, İran ve Basra Körfezi'nde ciddi bir itibar kaybına yol açar; Birleşik Krallık ve ABD'de de profesyonellik dışı görülür. Her zaman baş başa konuş. Birçok İngiliz şirketinde yazılı uyarı, bunun gibi gayriresmî bir konuşmadan önce değil, sonra gelmesi gereken resmî bir sürecin parçasıdır.","fa":"مطرح کردن رفتار کسی جلوی همکارانش، در ترکیه، ایران و کشورهای حاشیه‌ی خلیج فارس ضربه‌ی جدی‌ای به آبروی او می‌زند و در بریتانیا و آمریکا هم کاری غیرحرفه‌ای به حساب می‌آید. همیشه در خلوت صحبت کن. در بسیاری از شرکت‌های بریتانیایی، اخطار کتبی بخشی از یک روند رسمی است و باید بعد از یک گفتگوی غیررسمی مثل همین بیاید، نه قبل از آن."},"model":"Thanks for coming, Deniz. I wanted to talk about something I've noticed. You've arrived late four times in the last two weeks, and that isn't like you: in April you were early every day. Can you help me understand what's been happening? I see. If we moved your start to 8:30 for a month, would that help? And if anything changes, please tell Omar the day before.","selfCheck":[{"en":"I opened in private and said why we were meeting.","tr":"Görüşmeyi baş başa açtım ve neden konuştuğumuzu söyledim.","fa":"گفتگو را در خلوت شروع کردم و گفتم چرا جلسه گذاشته‌ایم."},{"en":"I gave facts with 'I've noticed' and one positive note.","tr":"'I've noticed' ile bilgileri ve bir olumlu not verdim.","fa":"واقعیت‌ها را با «I've noticed» و یک نکته‌ی مثبت گفتم."},{"en":"I asked what had been happening before offering a solution.","tr":"Çözüm önermeden önce neler olduğunu sordum.","fa":"پیش از پیشنهاد راه‌حل پرسیدم چه اتفاقی افتاده."},{"en":"My solution used 'If we..., would...?' and one clear expectation.","tr":"Çözümümde 'If we..., would...?' ve net bir beklenti vardı.","fa":"راه‌حلم با «⁨If we..., would...?⁩» و یک انتظار روشن بود."}]},"branch":{"id":"c-hr-4-4-b","course":"hr","unit":"hr-4-4","type":"branch","title":{"en":"The Lateness Conversation","tr":"Geç Kalma Konuşması","fa":"گفتگو درباره‌ی تأخیر"},"setting":{"en":"A small private meeting room in Dubai. You are Leyla. Deniz has been late four times in two weeks. Choose what to say. If a choice goes badly, you will see what happens and can try again.","tr":"Dubai'de küçük, özel bir toplantı odası. Sen Leyla'sın. Deniz iki haftada dört kez geç kaldı. Ne söyleyeceğini seç. Bir seçim kötü giderse ne olduğunu görürsün ve yeniden deneyebilirsin.","fa":"یک اتاق جلسه‌ی کوچک و خصوصی در دبی. تو لیلا هستی. دنیز در دو هفته‌ی گذشته چهار بار دیر آمده است. انتخاب کن چه بگویی. اگر انتخابی خوب پیش نرود، نتیجه‌اش را می‌بینی و می‌توانی دوباره امتحان کنی."},"start":"n1","nodes":{"n1":{"speaker":"Deniz","line":"You wanted to see me?","choices":[{"text":"Thanks for coming. I wanted to talk about something I've noticed. Is now a good time?","tone":"good","next":"n2","reply":"Yes... okay.","feedback":{"en":"Private, friendly and you name the purpose. Good start.","tr":"Özel, samimi ve amacı belirtiyorsun. İyi bir başlangıç.","fa":"خصوصی، دوستانه و هدف جلسه را هم گفتی. شروع خوبی است."}},{"text":"Yes. You've been late again, and Omar is very angry.","tone":"poor","next":"n1","reply":"(Deniz goes pale and looks at the floor.) Sorry.","feedback":{"en":"Blame and someone else's anger close the conversation before it starts. Try a calm opening.","tr":"Suçlama ve başkasının öfkesi konuşmayı başlamadan kapatır. Sakin bir açılış dene.","fa":"سرزنش کردن و حرف زدن از عصبانیت یک نفر دیگر، گفتگو را پیش از شروع تمام می‌کند. آرام شروع کن."}},{"text":"Let's just chat first. Hot today, isn't it?","tone":"ok","next":"n2","reply":"Yes... very hot. (He still looks worried.)","feedback":{"en":"Kind, but he knows something is wrong. Small talk only delays it; name the purpose soon.","tr":"Nazik, ama bir sorun olduğunu biliyor. Sohbet sadece geciktirir; amacı kısa sürede söyle.","fa":"مهربانانه است، اما او می‌داند مشکلی در کار است. گپ زدن فقط اصل موضوع را عقب می‌اندازد؛ زودتر هدف جلسه را بگو."}}]},"n2":{"speaker":"Deniz","line":"Is something wrong?","choices":[{"text":"I've noticed that you've arrived late four times in the last two weeks, about twenty minutes each time. That isn't like you.","tone":"good","next":"n3","reply":"(He looks down.) I know. I'm sorry.","feedback":{"en":"Specific facts, no labels, and a positive note about him.","tr":"Somut olgular, etiket yok ve onun hakkında olumlu bir not.","fa":"واقعیت‌های مشخص، بدون برچسب زدن و یک نکته‌ی مثبت درباره‌ی خودش. عالی است."}},{"text":"You're always late. Honestly, it looks unreliable.","tone":"poor","next":"n2","reply":"Always? That's not fair. I was early every day in April!","feedback":{"en":"\"Always\" and labels like \"unreliable\" start an argument. Give the facts: how many times and how late.","tr":"\"Always\" ve \"unreliable\" gibi etiketler tartışma başlatır. Olguları ver: kaç kez ve ne kadar geç.","fa":"«همیشه» و برچسب‌هایی مثل «غیرقابل اعتماد» بحث را به دعوا می‌کشانند. واقعیت را بگو: چند بار و چقدر دیر."}},{"text":"There have been some timing issues recently.","tone":"ok","next":"n2","reply":"Timing issues? With the trucks?","feedback":{"en":"Too vague: he does not know what you mean. Say exactly what you noticed.","tr":"Fazla belirsiz: ne demek istediğini anlamıyor. Tam olarak ne fark ettiğini söyle.","fa":"بیش از حد کلی است؛ متوجه نمی‌شود منظورت چیست. دقیقاً بگو چه دیده‌ای."}}]},"n3":{"speaker":"Deniz","line":"I'm sorry. It won't happen again.","choices":[{"text":"Thank you. Before we talk about solutions, can you help me understand what's been happening?","tone":"good","next":"n4","reply":"My sister had an operation. I take her daughter to school at 7:30 now. The school is on the other side of the city.","feedback":{"en":"You asked before you judged, so now you know the real reason.","tr":"Yargılamadan önce sordun, artık gerçek sebebi biliyorsun.","fa":"قبل از قضاوت پرسیدی، و حالا دلیل واقعی را می‌دانی."}},{"text":"Good. If it happens again, you'll get a written warning.","tone":"poor","next":"n3","reply":"(He says \"Okay\" and leaves quickly. The next Monday he is late again, and nobody knows why.)","feedback":{"en":"A threat without understanding keeps the problem hidden. Ask what is happening first.","tr":"Anlamadan yapılan bir tehdit sorunu gizli tutar. Önce neler olduğunu sor.","fa":"اگر پیش از فهمیدن ماجرا تهدید کنی، مشکل پنهان می‌ماند. اول بپرس چه اتفاقی افتاده است."}},{"text":"Is everything all right at home?","tone":"ok","next":"n4","reply":"It's... family things. My sister had an operation, and I take her daughter to school now.","feedback":{"en":"Caring, but it guesses at his private life. An open question (\"what's been happening?\") lets him choose what to share.","tr":"Şefkatli, ama özel hayatı hakkında tahmin yürütüyor. Açık bir soru (\"what's been happening?\") neyi paylaşacağını ona bırakır.","fa":"دلسوزانه است، اما درباره‌ی زندگی خصوصی‌اش حدس می‌زنی. یک سؤال باز («⁨what's been happening?⁩») به او اجازه می‌دهد خودش انتخاب کند چه چیزی را بگوید."}}]},"n4":{"speaker":"Deniz","line":"I didn't tell anyone. New people don't bring problems.","choices":[{"text":"Thank you for telling me. If we moved your start to 8:30 for the next month, would that help? And if anything changes, please tell Omar or me the day before.","tone":"good","next":"end","reply":"Yes. That would really help. Thank you.","feedback":{"en":"A clear offer with a time limit, and a clear expectation for next time.","tr":"Süre sınırı olan net bir teklif ve bir dahaki sefer için net bir beklenti.","fa":"یک پیشنهاد روشن با مدت مشخص و یک انتظار روشن برای دفعه‌ی بعد."}},{"text":"I understand, but rules are rules. Everyone starts at 7:30.","tone":"poor","next":"n4","reply":"Then I don't know what to do.","feedback":{"en":"A fair rule can still be adjusted for a short time. Offer a realistic option: \"If we..., would...?\"","tr":"Adil bir kural kısa bir süre için yine de uyarlanabilir. Gerçekçi bir seçenek sun: \"If we..., would...?\"","fa":"یک قانون منصفانه را هم می‌شود برای مدتی کوتاه تعدیل کرد. یک گزینه‌ی واقع‌بینانه پیشنهاد کن: «⁨If we..., would...?⁩»"}},{"text":"That's hard. Let me talk to Omar and get back to you.","tone":"ok","next":"n4","reply":"Okay... but what do I do tomorrow morning?","feedback":{"en":"Kind, but he leaves with nothing for tomorrow. Offer one concrete step now.","tr":"Nazik, ama yarın için elinde hiçbir şey olmadan çıkıyor. Şimdi somut bir adım öner.","fa":"مهربانانه است، اما او برای فردا دست خالی از اتاق بیرون می‌رود. همین حالا یک قدم مشخص پیشنهاد کن."}}]},"end":{"end":true,"outcome":{"en":"Deniz starts at 8:30 for a month and is on time every day. When the school has a holiday, he tells Omar the day before. You send both of them a short note of what you agreed.","tr":"Deniz bir ay boyunca 8:30'da başlıyor ve her gün zamanında geliyor. Okul tatil olduğunda Omar'a bir gün önceden haber veriyor. Kararlaştırdıklarınızı ikisine de kısa bir notla gönderiyorsun.","fa":"دنیز یک ماه از ساعت ۸:۳۰ کارش را شروع می‌کند و هر روز سر وقت می‌رسد. هر وقت مدرسه تعطیل باشد، یک روز قبل به عمر خبر می‌دهد. تو هم یادداشت کوتاهی از توافقت را برای هر دو نفر می‌فرستی."}}}},"writing":{"id":"c-hr-4-4-w","title":{"en":"A note to Deniz about the agreement","tr":"Anlaşma hakkında Deniz'e not","fa":"یادداشتی برای دنیز درباره‌ی توافق"},"course":"hr","unit":"hr-4-4","type":"writing","difficulty":"medium","prompt":{"en":"Write a short note to Deniz (copy to Omar) confirming what you agreed (45-70 words): the new start time, how long it lasts, the expectation, and when you will check in.","tr":"Deniz'e (Omar'a bilgi olarak) kararlaştırdıklarınızı teyit eden kısa bir not yaz (45-70 kelime): yeni başlama saati, ne kadar süreceği, beklenti ve ne zaman tekrar görüşeceğiniz.","fa":"یک یادداشت کوتاه برای دنیز (با رونوشت به عمر) بنویس و آنچه را توافق کردی تأیید کن (۴۵ تا ۷۰ کلمه): ساعت شروع جدید، تا چه مدت، انتظاری که از او داری و زمان جلسه‌ی پیگیری."},"model":"Hi Deniz, thank you for our talk today. As agreed, from Monday 12 May your start time on Route 7 will be 8:30 for four weeks, and you will finish at 5:30. If anything changes, please tell Omar or me the day before. We will check in again on Friday 6 June. I hope your sister feels better soon. Best, Leyla","frame":"Hi ___, thank you for ___. As agreed, from ___ your start time will be ___ for ___. If anything changes, please ___. We will check in again on ___. Best, ___","words":[{"word":"as agreed"},{"word":"start time"},{"word":"check in"}],"minWords":45,"minSentences":4,"rubric":["Task done: new time, duration, expectation, check-in date","Organised: agreement first, then expectation and next date","Language: will for the plan; if + present for the expectation","Tone: supportive and clear; no blame, no private details for Omar"],"rubricI18n":{"tr":["Görev: yeni saat, süre, beklenti, ara görüşme tarihi","Düzen: önce anlaşma, sonra beklenti ve sonraki tarih","Dil: plan için will; beklenti için if + present","Üslup: destekleyici ve net; suçlama yok, Omar'a özel ayrıntı yok"],"fa":["کامل بودن کار: ساعت جدید، مدت، انتظار، تاریخ جلسه‌ی پیگیری","نظم: اول توافق، بعد انتظار و تاریخ بعدی","زبان: will برای برنامه؛ if با حال ساده برای انتظار","لحن: حمایتگر و روشن؛ بدون سرزنش و بدون جزئیات خصوصی برای عمر"]},"portfolio":null,"parts":[{"t":{"en":"The new start time","tr":"Yeni başlama saati","fa":"ساعت شروع تازه"},"find":["start time","will be","from monday"],"sample":"8:30 on Route 7 from Monday 12 May"},{"t":{"en":"How long it lasts","tr":"Ne kadar süreceği","fa":"اینکه چقدر طول می‌کشد"},"find":["for four weeks","weeks","until"],"sample":"four weeks"},{"t":{"en":"What you expect","tr":"Beklentin","fa":"انتظارت"},"find":["if anything changes","please tell","the day before"],"sample":"tell Omar or me the day before"},{"t":{"en":"The check-in date","tr":"Yeniden görüşme tarihi","fa":"تاریخ گفتگوی بعدی"},"find":["check in","check-in"],"sample":"Friday 6 June"}]},"perspective":{"id":"c-hr-4-4-p","title":{"en":"Deniz the night before","tr":"Önceki gece Deniz","fa":"دنیز، شب قبل"},"course":"hr","unit":"hr-4-4","type":"perspective","minSentences":2,"prompt":{"en":"You are Deniz the night before the meeting. Write 2 sentences in first person: what is happening at home, and why haven't you told anyone at work?","tr":"Toplantıdan önceki gece Deniz'sin. Birinci tekil şahısla 2 cümle yaz: evde neler oluyor ve neden işte kimseye söylemedin?","fa":"تو دنیز هستی، شب قبل از جلسه. از زبان خودت دو جمله بنویس: در خانه چه خبر است، و چرا به هیچ‌کس در محل کار چیزی نگفته‌ای؟"}},"exit":{"id":"c-hr-4-4-x","course":"hr","unit":"hr-4-4","type":"exit","items":[{"from":"hr-4-4","kind":"blank","prompt":"If we ___ your break, would that help?","options":["will move","moved","have moved"],"correct":1,"point":2,"why":{"en":"moved: 'If we..., would that help?' offers a possible change, so if + past. 'Will move' and 'have moved' don't go with would.","tr":"moved: 'If we..., would that help?' olası bir değişiklik önerir, bu yüzden if + geçmiş. 'Will move' ve 'have moved' would ile gelmez.","fa":"moved درست است، چون If we..., would that help? یک تغییر احتمالی پیشنهاد می‌کند و بعد از if گذشته می‌آید. will move و have moved با would جور نیستند."}},{"from":"hr-4-4","kind":"blank","prompt":"I've ___ that the van was left unlocked twice.","options":["noticed","notice","noticing"],"correct":0,"point":2,"why":{"en":"noticed: 'I've' + past participle. 'Notice' and 'noticing' are not past participles.","tr":"noticed: 'I've' + üçüncü hâl. 'Notice' ve 'noticing' üçüncü hâl değildir.","fa":"noticed درست است، چون I've با اسم مفعول می‌آید. notice و noticing اسم مفعول نیستند."},"hint2":{"en":"I’ve is the start of the present perfect. Which verb form comes after have?","tr":"I’ve, present perfect’in başlangıcıdır. have’den sonra fiilin hangi biçimi gelir?","fa":"⁨I’ve⁩ شروعِ زمان حال کامل است. بعد از ⁨have⁩ فعل با چه شکلی می‌آید؟"}},{"from":"hr-4-4","kind":"mcq","prompt":"Which opening is fair and specific?","options":["You're always late.","I've noticed you've arrived late four times in two weeks.","Omar is angry with you."],"correct":1,"point":1,"why":{"en":"'I've noticed you've arrived late four times in two weeks' starts from facts. 'Always' is unfair, and bringing in Omar's anger makes it personal.","tr":"'I've noticed you've arrived late four times in two weeks' bilgilerden başlar. 'Always' haksızdır; Omar'ın öfkesini işe katmak konuyu kişiselleştirir.","fa":"«I've noticed you've arrived late four times in two weeks» از واقعیت‌ها شروع می‌کند. always منصفانه نیست و آوردن عصبانیت Omar ماجرا را شخصی می‌کند."}},{"from":"hr-4-3","kind":"blank","prompt":"It sounds ___ nobody asked you first.","options":["like","that","so"],"correct":0,"point":2,"why":{"en":"like: 'It sounds like' + a clause. 'Sounds that' and 'sounds so' are not English.","tr":"like: 'It sounds like' + yan cümle. 'Sounds that' ve 'sounds so' İngilizce değildir.","fa":"like درست است، چون الگو It sounds like و بعد جمله است. sounds that و sounds so انگلیسی نیستند."},"hint2":{"en":"After sounds, a whole clause follows (nobody asked you first). One small word joins sounds to a clause.","tr":"sounds’tan sonra tam bir yan cümle geliyor (nobody asked you first). sounds’u yan cümleye küçük bir kelime bağlar.","fa":"بعد از ⁨sounds⁩ یک جمله‌ی کامل آمده (⁨nobody asked you first⁩). یک کلمه‌ی کوچک ⁨sounds⁩ را به جمله وصل می‌کند."}},{"from":"hr-4-1","kind":"blank","prompt":"If the depot ___ closed, call the night line.","options":["will be","is","would be"],"correct":1,"point":2,"why":{"en":"is: a real condition takes if + present. 'Will be' and 'would be' are wrong after if here.","tr":"is: gerçek bir koşul if + geniş zaman alır. Burada if'ten sonra 'will be' ve 'would be' yanlıştır.","fa":"is درست است، چون شرط واقعی با if و حال ساده می‌آید. will be و would be اینجا بعد از if غلط‌اند."}},{"from":"hr-3-1","kind":"blank","prompt":"First I'll explain the role, then you'll ___ a chance to ask questions.","options":["have","having","to have"],"correct":0,"point":2,"why":{"en":"have: after 'you'll', use the plain verb. 'Having' and 'to have' don't follow will.","tr":"have: 'you'll'dan sonra yalın fiil gelir. 'Having' ve 'to have' will'den sonra gelmez.","fa":"have درست است، چون بعد از you'll فعل ساده می‌آید. having و to have بعد از will نمی‌آیند."}}]}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
